```python
# API mínima con Flask que devuelve un saludo en JSON
from flask import Flask, jsonify

app = Flask(__name__)

@app.route("/v1/hello/<string:name>", methods=["GET"])
def hello(name):
    return jsonify({"message": f"Hola, {name}!"}), 200

if __name__ == "__main__":
    app.run(debug=True)
```
